var cotType = 'b-m-p-s-m';
var colorValue = -16776961; // blue -- water
var channelName = 'USGS Streamflow';
var staleHours = 20 / 60; // USGS IV data updates every 15-60 min

function esc(s) {
    return String(s == null ? '' : s)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;')
        .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

var allSeries = (msg.payload && msg.payload.value && msg.payload.value.timeSeries) || [];
var sites = {};

allSeries.forEach(function (ts) {
    var src = ts.sourceInfo;
    if (!src) { return; }
    var siteCode = src.siteCode && src.siteCode[0] && src.siteCode[0].value;
    if (!siteCode) { return; }
    var geo = src.geoLocation && src.geoLocation.geogLocation;
    if (!geo) { return; }

    if (!sites[siteCode]) {
        sites[siteCode] = {
            name: src.siteName || ('Site ' + siteCode),
            lat: parseFloat(geo.latitude),
            lon: parseFloat(geo.longitude),
            params: []
        };
    }

    var varInfo = ts.variable || {};
    var varName = (varInfo.variableName || 'value').split(',')[0];
    var latestVal = ts.values && ts.values[0] && ts.values[0].value && ts.values[0].value[0];
    if (latestVal) {
        sites[siteCode].params.push({
            name: varName,
            value: latestVal.value,
            dateTime: latestVal.dateTime
        });
    }
});

var msgs = [];
Object.keys(sites).forEach(function (siteCode) {
    var s = sites[siteCode];
    if (!s.lat || !s.lon || !s.params.length) { return; }

    var now = new Date();
    var start = now.toISOString();
    var stale = new Date(now.getTime() + staleHours * 3600000).toISOString();
    var uid = 'usgs-water-' + siteCode;

    var remarksParts = [s.name, 'Site ' + siteCode];
    s.params.forEach(function (p) {
        remarksParts.push(p.name + ': ' + p.value + ' (as of ' + p.dateTime + ')');
    });

    var cot = '<?xml version="1.0" encoding="UTF-8"?>' +
        '<event version="2.0" uid="' + esc(uid) + '" type="' + cotType + '" how="m-g" ' +
        'time="' + start + '" start="' + start + '" stale="' + stale + '">' +
        '<point lat="' + s.lat + '" lon="' + s.lon + '" hae="0" ce="9999999.0" le="9999999.0"/>' +
        '<detail>' +
        '<contact callsign="' + esc(s.name) + '"/>' +
        '<color value="' + colorValue + '"/>' +
        '<remarks>' + esc(remarksParts.join(' | ')) + '</remarks>' +
        '<marti><dest name="' + esc(channelName) + '"/></marti>' +
        '</detail>' +
        '</event>';

    msgs.push({ payload: cot });
});

node.status({ fill: 'blue', shape: 'dot', text: msgs.length + ' gauges in TN bbox' });
if (!msgs.length) { return null; }
return [msgs];
